-- Diapasón — datos de muestra migrados desde src/data/products.json.
-- Pégalo en el SQL Editor DESPUÉS de products.sql. Es seguro re-ejecutarlo:
-- usa el slug como clave y no duplica filas (upsert).

on conflict (slug) do update set
  name = excluded.name,
  brand = excluded.brand,
  category_slug = excluded.category_slug,
  subcategory_slug = excluded.subcategory_slug,
  price = excluded.price,
  description = excluded.description,
  stock = excluded.stock,
  is_new = excluded.is_new,
  images = excluded.images,
  specs = excluded.specs;
