insert into public.products
  (slug, name, brand, category_slug, subcategory_slug, price, description, stock, is_new, images, specs)
values
  ('cordoba-c7-cedro', 'C7 Cedro', 'Córdoba', 'guitarras', 'clasicas', 399, 'Una clásica de concierto de entrada seria: tapa de cedro macizo y aros de palosanto que dan un bajo redondo y un ataque cálido. Sale del taller con cuerdas nuevas y la altura fijada para estudio y escenario.', 12, true, ARRAY['https://images.unsplash.com/photo-1501059104508-e158516511cd?auto=format&fit=crop&w=1100&h=1375&q=70','https://images.unsplash.com/photo-1525201548942-d8732f6617a0?auto=format&fit=crop&w=1100&h=1375&q=70']::text[], '[{"label": "Tapa", "value": "Cedro macizo"}, {"label": "Aros y fondo", "value": "Palosanto laminado"}, {"label": "Diapasón", "value": "Ébano, 52 mm en cejuela"}, {"label": "Escala", "value": "650 mm"}, {"label": "Acabado", "value": "Poliuretano satinado"}, {"label": "Incluye", "value": "Funda acolchada 20 mm"}]'::jsonb),
  ('fender-player-ii-strat', 'Player II Stratocaster', 'Fender', 'guitarras', 'electricas', 899, 'El caballo de batalla de mil discos, ahora con trastes más altos y mástil en C moderno. Tres pastillas de bobina simple que van del funk limpio al blues con drive sin perder el brillo característico.', 12, false, ARRAY['https://images.unsplash.com/photo-1763518372027-6978e6bf5885?auto=format&fit=crop&w=1100&h=1375&q=70','https://images.unsplash.com/photo-1516924962500-2b4b3b99ea02?auto=format&fit=crop&w=1100&h=1375&q=70']::text[], '[{"label": "Cuerpo", "value": "Aliso"}, {"label": "Mástil", "value": "Arce, perfil C moderno"}, {"label": "Pastillas", "value": "3x Player II single-coil"}, {"label": "Puente", "value": "Trémolo vintage de 6 tornillos"}, {"label": "Trastes", "value": "22 medium jumbo"}, {"label": "Escala", "value": "648 mm (25.5\")"}]'::jsonb),
  ('taylor-gs-mini-koa', 'GS Mini-e Koa', 'Taylor', 'guitarras', 'acusticas', 799, 'Cuerpo reducido con proyección de guitarra grande y una tapa de koa que gana dulzura con las horas de uso. Trae electrónica ES-B con afinador integrado para pasar de la sala al escenario sin cambiar nada.', 12, true, ARRAY['https://images.unsplash.com/photo-1605020420620-20c943cc4669?auto=format&fit=crop&w=1100&h=1375&q=70','https://images.unsplash.com/photo-1501059104508-e158516511cd?auto=format&fit=crop&w=1100&h=1375&q=70']::text[], '[{"label": "Tapa", "value": "Koa laminada"}, {"label": "Aros y fondo", "value": "Koa laminada"}, {"label": "Cuerpo", "value": "GS Mini (grand symphony reducido)"}, {"label": "Electrónica", "value": "Taylor ES-B con afinador"}, {"label": "Escala", "value": "597 mm (23.5\")"}, {"label": "Incluye", "value": "Funda Taylor estructurada"}]'::jsonb),
  ('gibson-les-paul-studio', 'Les Paul Studio', 'Gibson', 'guitarras', 'electricas', 1499, 'Toda la voz de una Les Paul —caoba con tapa de arce y dos humbuckers calientes— sin los adornos que encarecen el modelo Standard. Peso aliviado y acabado satinado que no frena la mano izquierda.', 0, false, ARRAY['https://images.unsplash.com/photo-1516924962500-2b4b3b99ea02?auto=format&fit=crop&w=1100&h=1375&q=70','https://images.unsplash.com/photo-1550291652-6ea9114a47b1?auto=format&fit=crop&w=1100&h=1375&q=70']::text[], '[{"label": "Cuerpo", "value": "Caoba con tapa de arce AA"}, {"label": "Mástil", "value": "Caoba, perfil SlimTaper"}, {"label": "Pastillas", "value": "490R / 498T humbucker"}, {"label": "Puente", "value": "Tune-o-matic con stopbar de aluminio"}, {"label": "Electrónica", "value": "4 controles, push-pull de coil tap"}, {"label": "Escala", "value": "628 mm (24.75\")"}]'::jsonb),
  ('yamaha-trbx304', 'TRBX304', 'Yamaha', 'guitarras', 'bajos', 329, 'Un bajo de cuatro cuerdas versátil con mástil de cinco piezas y circuito activo Performance EQ que ofrece cinco escenas sonoras con un botón. Cómodo para manos chicas y estable en afinación.', 12, false, ARRAY['https://images.unsplash.com/photo-1564264764238-7e04d6b46f9c?auto=format&fit=crop&w=1100&h=1375&q=70','https://images.unsplash.com/photo-1550291652-6ea9114a47b1?auto=format&fit=crop&w=1100&h=1375&q=70']::text[], '[{"label": "Cuerpo", "value": "Caoba"}, {"label": "Mástil", "value": "Arce y caoba, 5 piezas, atornillado"}, {"label": "Pastillas", "value": "2x humbucker cerámico"}, {"label": "Electrónica", "value": "Activa, Performance EQ de 5 modos"}, {"label": "Escala", "value": "864 mm (34\")"}, {"label": "Puente", "value": "Die-cast Vintage Plus"}]'::jsonb),
  ('alhambra-3c', '3C', 'Alhambra', 'guitarras', 'clasicas', 349, 'La española de estudio que recomendamos para conservatorio: tapa de cedro macizo hecha en Muro de Alcoy y una respuesta noble que aguanta años de práctica. Relación precio-sonido difícil de igualar.', 12, false, ARRAY['https://images.unsplash.com/photo-1525201548942-d8732f6617a0?auto=format&fit=crop&w=1100&h=1375&q=70','https://images.unsplash.com/photo-1501059104508-e158516511cd?auto=format&fit=crop&w=1100&h=1375&q=70']::text[], '[{"label": "Tapa", "value": "Cedro macizo"}, {"label": "Aros y fondo", "value": "Sapelly"}, {"label": "Mástil", "value": "Caoba con refuerzo"}, {"label": "Diapasón", "value": "Palosanto"}, {"label": "Escala", "value": "650 mm"}, {"label": "Origen", "value": "Muro de Alcoy, España"}]'::jsonb),
  ('prs-se-custom-24', 'SE Custom 24', 'PRS', 'guitarras', 'electricas', 899, 'El puente de la marca entre lo accesible y lo profesional: tapa de arce flameado, 24 trastes y pastillas 85/15 S que limpian bien y aprietan cuando subes el volumen. Trémolo estable que vuelve a afinación.', 12, true, ARRAY['https://images.unsplash.com/photo-1550985616-10810253b84d?auto=format&fit=crop&w=1100&h=1375&q=70','https://images.unsplash.com/photo-1516924962500-2b4b3b99ea02?auto=format&fit=crop&w=1100&h=1375&q=70']::text[], '[{"label": "Cuerpo", "value": "Caoba con tapa de arce flameado"}, {"label": "Mástil", "value": "Arce, perfil Wide Thin"}, {"label": "Pastillas", "value": "PRS 85/15 S humbucker"}, {"label": "Trastes", "value": "24, escala 635 mm (25\")"}, {"label": "Puente", "value": "Trémolo PRS patentado"}, {"label": "Electrónica", "value": "Volumen, tono, selector de 3 vías con push-pull"}]'::jsonb),
  ('martin-d-10e', 'D-10E', 'Martin', 'guitarras', 'acusticas', 999, 'Dreadnought de maderas macizas —abeto Sitka y sapelly— con el bajo firme que define el sonido Martin para acompañar voz. Trae previo Fishman MX-T con afinador oculto en la boca.', 12, false, ARRAY['https://images.unsplash.com/photo-1605020420620-20c943cc4669?auto=format&fit=crop&w=1100&h=1375&q=70','https://images.unsplash.com/photo-1525201548942-d8732f6617a0?auto=format&fit=crop&w=1100&h=1375&q=70']::text[], '[{"label": "Tapa", "value": "Abeto Sitka macizo"}, {"label": "Aros y fondo", "value": "Sapelly macizo"}, {"label": "Cuerpo", "value": "Dreadnought"}, {"label": "Electrónica", "value": "Fishman MX-T con afinador"}, {"label": "Mástil", "value": "Select hardwood, perfil Performing Artist"}, {"label": "Incluye", "value": "Estuche blando Martin"}]'::jsonb),
  ('roland-fp-30x', 'FP-30X', 'Roland', 'teclados', 'pianos-digitales', 699, 'El piano digital portátil que más recomendamos para empezar en casa: teclado PHA-4 con escape y marfil sintético, y el motor SuperNATURAL con más cuerpo que la generación anterior. Bluetooth para apps y bocinas internas de 22 W.', 12, false, ARRAY['https://images.unsplash.com/photo-1546058256-47154de4046c?auto=format&fit=crop&w=1100&h=1375&q=70','https://images.unsplash.com/photo-1520523839897-bd0b52f945a0?auto=format&fit=crop&w=1100&h=1375&q=70']::text[], '[{"label": "Teclas", "value": "88, PHA-4 Standard con contrapeso y escape"}, {"label": "Polifonía", "value": "256 voces"}, {"label": "Sonidos", "value": "56, motor SuperNATURAL Piano"}, {"label": "Amplificación", "value": "2x 11 W"}, {"label": "Conectividad", "value": "USB, Bluetooth MIDI/Audio, 2x jack audífonos"}, {"label": "Peso", "value": "14.8 kg"}]'::jsonb),
  ('korg-minilogue-xd', 'minilogue xd', 'Korg', 'teclados', 'sintetizadores', 649, 'Analógico polifónico de cuatro voces con un motor digital multiengine para meter FM, ruido y osciladores de usuario. El delantero de aluminio y los 37 teclas Slim lo hacen viajero sin sacrificar edición directa.', 12, true, ARRAY['https://images.unsplash.com/photo-1776785941157-a1b8c3890300?auto=format&fit=crop&w=1100&h=1375&q=70','https://images.unsplash.com/photo-1512733596533-7b00ccf8ebaf?auto=format&fit=crop&w=1100&h=1375&q=70']::text[], '[{"label": "Voces", "value": "4, analógico polifónico"}, {"label": "Osciladores", "value": "2 VCO analógicos + Multi Engine digital"}, {"label": "Teclas", "value": "37 Slim, sensibles a velocidad"}, {"label": "Efectos", "value": "Mod, reverb y delay digitales"}, {"label": "Secuenciador", "value": "16 pasos con motion sequencing"}, {"label": "Salidas", "value": "Audio L/R, sync, MIDI DIN, USB"}]'::jsonb),
  ('nord-stage-4-compact', 'Stage 4 Compact', 'Nord', 'teclados', 'organos', 3499, 'El teclado de escenario de referencia: secciones independientes de piano, órgano y sintetizador con faders dedicados y morphing en tiempo real. El Compact monta 73 teclas semicontrapesadas con waterfall para el órgano.', 0, true, ARRAY['https://images.unsplash.com/photo-1470019693664-1d202d2c0907?auto=format&fit=crop&w=1100&h=1375&q=70','https://images.unsplash.com/photo-1546058256-47154de4046c?auto=format&fit=crop&w=1100&h=1375&q=70']::text[], '[{"label": "Teclas", "value": "73 semicontrapesadas waterfall"}, {"label": "Piano", "value": "2 GB de memoria de muestras"}, {"label": "Órgano", "value": "Modelos B3, Vox, Farfisa y pipe"}, {"label": "Síntesis", "value": "Nord Wave 2, tabla de ondas y muestras"}, {"label": "Efectos", "value": "Dos secciones por capa + reverb y compresor globales"}, {"label": "Peso", "value": "9.3 kg"}]'::jsonb),
  ('akai-mpk-mini-mk3', 'MPK mini mk3', 'Akai', 'teclados', 'controladores', 119, 'El controlador de escritorio más vendido para producción: 25 mini teclas, 8 pads con luz y un joystick 4 vías para modulación. Se alimenta por USB y llega con paquete de software para arrancar el mismo día.', 12, false, ARRAY['https://images.unsplash.com/photo-1512733596533-7b00ccf8ebaf?auto=format&fit=crop&w=1100&h=1375&q=70','https://images.unsplash.com/photo-1776785941157-a1b8c3890300?auto=format&fit=crop&w=1100&h=1375&q=70']::text[], '[{"label": "Teclas", "value": "25 mini, sensibles a velocidad"}, {"label": "Pads", "value": "8 retroiluminados, banco A/B"}, {"label": "Controles", "value": "8 potenciómetros sin fin, joystick 4 vías"}, {"label": "Pantalla", "value": "OLED"}, {"label": "Conexión", "value": "USB-C, clase compliant"}, {"label": "Incluye", "value": "MPC Beats + instrumentos virtuales"}]'::jsonb),
  ('yamaha-p-145', 'P-145', 'Yamaha', 'teclados', 'pianos-digitales', 549, 'La renovación del clásico P-45 para quien quiere un piano de 88 teclas sin gastar de más. Teclado GHC con contrapeso graduado y muestras del gran cola CFX de Yamaha, en un chasis de apenas 11 kg.', 12, true, ARRAY['https://images.unsplash.com/photo-1520523839897-bd0b52f945a0?auto=format&fit=crop&w=1100&h=1375&q=70','https://images.unsplash.com/photo-1546058256-47154de4046c?auto=format&fit=crop&w=1100&h=1375&q=70']::text[], '[{"label": "Teclas", "value": "88, GHC con contrapeso graduado"}, {"label": "Polifonía", "value": "192 voces"}, {"label": "Sonidos", "value": "10, muestreo CFX"}, {"label": "Amplificación", "value": "2x 7 W"}, {"label": "Conectividad", "value": "USB to Host, jack de audífonos, Smart Pianist"}, {"label": "Peso", "value": "11.1 kg"}]'::jsonb),
  ('hammond-sk-pro', 'SK Pro 61', 'Hammond', 'teclados', 'organos', 3299, 'El motor de órgano digital más creíble de Hammond en un formato transportable, con drawbars físicos y modelado de rotativo Leslie. Suma pianos, metales y sintetizador para cubrir todo un set sin un segundo teclado.', 0, false, ARRAY['https://images.unsplash.com/photo-1546058256-47154de4046c?auto=format&fit=crop&w=1100&h=1375&q=70','https://images.unsplash.com/photo-1512733596533-7b00ccf8ebaf?auto=format&fit=crop&w=1100&h=1375&q=70']::text[], '[{"label": "Teclas", "value": "61 waterfall, semicontrapesadas"}, {"label": "Órgano", "value": "Modelado MTW II, 9 drawbars físicos por manual"}, {"label": "Rotativo", "value": "Simulación Leslie con control de rampa"}, {"label": "Extra Voices", "value": "Pianos, metales, cuerdas y sintetizador de 8 voces"}, {"label": "Salidas", "value": "L/R balanceadas, audífonos, MIDI y USB audio"}, {"label": "Peso", "value": "8.2 kg"}]'::jsonb),
  ('yamaha-yas-280', 'YAS-280', 'Yamaha', 'vientos', 'saxofones', 999, 'El saxo alto de estudiante que aguanta años de banda escolar: mecánica precisa, afinación estable y una ergonomía pensada para manos que están aprendiendo. Sale del taller con revisión completa de zapatillas.', 12, false, ARRAY['https://images.unsplash.com/photo-1415201364774-f6f0bb35f28f?auto=format&fit=crop&w=1100&h=1375&q=70','https://images.unsplash.com/photo-1559553211-523e51d8fb08?auto=format&fit=crop&w=1100&h=1375&q=70']::text[], '[{"label": "Afinación", "value": "Mi bemol (alto)"}, {"label": "Cuerpo", "value": "Latón con laca dorada"}, {"label": "Llaves", "value": "Hasta Fa# agudo, apoyapulgar ajustable"}, {"label": "Boquilla", "value": "Yamaha 4C incluida"}, {"label": "Zapatillas", "value": "Piel con resonadores metálicos"}, {"label": "Incluye", "value": "Estuche mochila y accesorios de limpieza"}]'::jsonb),
  ('bach-tr300h2', 'TR300H2', 'Bach', 'vientos', 'trompetas', 799, 'Trompeta de estudio avanzado con campana de dos piezas y calibre medio-grande que da un centro de sonido firme sin exigir demasiado aire. Pistones de monel que se mantienen rápidos con mantenimiento básico.', 12, false, ARRAY['https://images.unsplash.com/photo-1573871669414-010dbf73ca84?auto=format&fit=crop&w=1100&h=1375&q=70']::text[], '[{"label": "Afinación", "value": "Si bemol"}, {"label": "Campana", "value": "Latón amarillo de 2 piezas, 123 mm"}, {"label": "Calibre", "value": ".459\" medio-grande"}, {"label": "Pistones", "value": "Monel niquelado"}, {"label": "Acabado", "value": "Laca clara"}, {"label": "Incluye", "value": "Boquilla Bach 7C y estuche rígido"}]'::jsonb),
  ('buffet-e11-clarinete', 'E11', 'Buffet Crampon', 'vientos', 'clarinetes', 899, 'Clarinete de granadillo macizo fabricado en Alemania con la digitación Boehm estándar y un timbre oscuro y homogéneo poco habitual en este rango. La elección clásica para dar el salto del plástico a la madera.', 12, true, ARRAY['https://images.unsplash.com/photo-1569791832138-fbdd9a500384?auto=format&fit=crop&w=1100&h=1375&q=70']::text[], '[{"label": "Afinación", "value": "Si bemol"}, {"label": "Cuerpo", "value": "Granadillo macizo (mpingo)"}, {"label": "Sistema", "value": "Boehm, 17 llaves y 6 anillos"}, {"label": "Llaves", "value": "Alpaca plateada"}, {"label": "Boquilla", "value": "Buffet con abrazadera y cañas"}, {"label": "Incluye", "value": "Estuche compacto y grasa de corcho"}]'::jsonb),
  ('pearl-quantz-505', 'Quantz 505 RBE', 'Pearl', 'vientos', 'flautas', 599, 'Flauta de estudio con mecanismo pointed key arm que mejora la respuesta y la sensación bajo los dedos. Configuración de platos abiertos y Mi mecánico para afinar mejor el registro agudo desde el primer día.', 12, false, ARRAY['https://images.unsplash.com/photo-1600771488491-c22d42a9347d?auto=format&fit=crop&w=1100&h=1375&q=70']::text[], '[{"label": "Cabeza", "value": "Alpaca plateada, corte Pearl"}, {"label": "Cuerpo", "value": "Alpaca plateada"}, {"label": "Platos", "value": "Abiertos (opción tapones incluidos)"}, {"label": "Mecánica", "value": "En línea con Mi mecánico y pointed key arms"}, {"label": "Pie", "value": "De Do"}, {"label": "Incluye", "value": "Estuche con funda y baqueta de limpieza"}]'::jsonb),
  ('selmer-sa80-ii', 'Serie II Jubilee', 'Selmer Paris', 'vientos', 'saxofones', 5999, 'El saxo alto profesional que ha definido el sonido de estudio durante décadas, en su edición Jubilee con mecánica revisada. Proyección enorme y una respuesta que premia el aire bien apoyado.', 0, true, ARRAY['https://images.unsplash.com/photo-1559553211-523e51d8fb08?auto=format&fit=crop&w=1100&h=1375&q=70','https://images.unsplash.com/photo-1415201364774-f6f0bb35f28f?auto=format&fit=crop&w=1100&h=1375&q=70']::text[], '[{"label": "Afinación", "value": "Mi bemol (alto)"}, {"label": "Cuerpo", "value": "Latón profesional, grabado a mano"}, {"label": "Acabado", "value": "Laca dorada Jubilee"}, {"label": "Llaves", "value": "Hasta Fa# agudo, apoyos ajustables"}, {"label": "Zapatillas", "value": "Piel seleccionada con resonadores metálicos"}, {"label": "Incluye", "value": "Estuche Selmer Light y boquilla S80 C*"}]'::jsonb),
  ('pearl-export-exx725', 'Export EXX725/C', 'Pearl', 'percusion', 'baterias-acusticas', 699, 'La batería más vendida de la historia por una razón: cascos de álamo y caoba que suenan grandes en vivo y herrajes fiables que no te dejan tirado. Incluye set de platillos Sabian SBR para tocar de inmediato.', 12, false, ARRAY['https://images.unsplash.com/photo-1543443258-92b04ad5ec6b?auto=format&fit=crop&w=1100&h=1375&q=70','https://images.unsplash.com/photo-1519892300165-cb5542fb47c7?auto=format&fit=crop&w=1100&h=1375&q=70']::text[], '[{"label": "Configuración", "value": "Bombo 22\", toms 10\"/12\"/16\", tarola 14\""}, {"label": "Cascos", "value": "Álamo y caoba, 6 capas"}, {"label": "Herrajes", "value": "830 Series, doble soporte"}, {"label": "Platillos", "value": "Sabian SBR 14\" hats, 16\" crash, 20\" ride"}, {"label": "Pedal", "value": "P-930 de leva redonda"}, {"label": "Acabado", "value": "Wrap, 6 colores disponibles"}]'::jsonb),
  ('roland-td-07kv', 'TD-07KV', 'Roland', 'percusion', 'baterias-electronicas', 899, 'Kit electrónico con tarola y platillos de malla que responden a matices reales, y el módulo TD-07 con motor de modelado tomado de la serie superior. Bluetooth de audio para tocar sobre pistas sin cables extra.', 12, true, ARRAY['https://images.unsplash.com/photo-1519892300165-cb5542fb47c7?auto=format&fit=crop&w=1100&h=1375&q=70','https://images.unsplash.com/photo-1571327073757-71d13c24de30?auto=format&fit=crop&w=1100&h=1375&q=70']::text[], '[{"label": "Módulo", "value": "TD-07, 25 kits, 143 sonidos"}, {"label": "Tarola", "value": "10\" malla de doble capa, con posición"}, {"label": "Toms", "value": "3x pad de goma con sensor doble"}, {"label": "Platillos", "value": "Hi-hat de 10\", crash y ride con zona de apagado"}, {"label": "Conectividad", "value": "Bluetooth audio/MIDI, USB, salida estéreo"}, {"label": "Rack", "value": "Plegable de aluminio"}]'::jsonb),
  ('meinl-headliner-cajon', 'Headliner Line Cajón', 'Meinl', 'percusion', 'cajones', 149, 'Cajón de tapa de abedul europeo con cuerdas fijas internas que dan un buzz seco y controlado para acompañar guitarra. Cantos superiores despegados para golpes de tono profundo sin lastimar la mano.', 12, false, ARRAY['https://images.unsplash.com/photo-1519892300165-cb5542fb47c7?auto=format&fit=crop&w=1100&h=1375&q=70','https://images.unsplash.com/photo-1543443258-92b04ad5ec6b?auto=format&fit=crop&w=1100&h=1375&q=70']::text[], '[{"label": "Tapa", "value": "Abedul europeo, esquinas despegadas"}, {"label": "Cuerpo", "value": "Abedul báltico, 11 capas"}, {"label": "Bordonera", "value": "Cuerdas internas fijas"}, {"label": "Medidas", "value": "48 x 30 x 30 cm"}, {"label": "Boca", "value": "Trasera de 12 cm"}, {"label": "Peso", "value": "5.2 kg"}]'::jsonb),
  ('zildjian-a-city-pack', 'A Zildjian City Pack', 'Zildjian', 'percusion', 'platillos', 549, 'Set compacto de la línea A —el sonido Zildjian de referencia— pensado para departamentos y estudios chicos: medidas reducidas que mantienen el brillo pero bajan el volumen. Trae funda de platillos incluida.', 12, true, ARRAY['https://images.unsplash.com/photo-1752090926254-a1b5f1f52998?auto=format&fit=crop&w=1100&h=1375&q=70','https://images.unsplash.com/photo-1571327073757-71d13c24de30?auto=format&fit=crop&w=1100&h=1375&q=70']::text[], '[{"label": "Hi-hats", "value": "13\" New Beat"}, {"label": "Crash", "value": "16\" A Thin Crash"}, {"label": "Ride", "value": "18\" Medium Thin Crash-Ride"}, {"label": "Aleación", "value": "B20 bronce fundido"}, {"label": "Acabado", "value": "Tradicional, torneado"}, {"label": "Incluye", "value": "Funda de nylon para platillos"}]'::jsonb),
  ('ludwig-supraphonic-lm400', 'Supraphonic LM400', 'Ludwig', 'percusion', 'baterias-acusticas', 449, 'La tarola más grabada de todos los tiempos: casco de aluminio hilado de 5" con un crack brillante y una afinación que funciona en cualquier estilo. Un estándar que rara vez sale de un estudio.', 0, false, ARRAY['https://images.unsplash.com/photo-1571327073757-71d13c24de30?auto=format&fit=crop&w=1100&h=1375&q=70','https://images.unsplash.com/photo-1752090926254-a1b5f1f52998?auto=format&fit=crop&w=1100&h=1375&q=70']::text[], '[{"label": "Medidas", "value": "14\" x 5\""}, {"label": "Casco", "value": "Aluminio Ludalloy hilado"}, {"label": "Aros", "value": "Triple flange de 2.3 mm"}, {"label": "Bordonera", "value": "Ludwig P-85 de 20 hilos"}, {"label": "Parche", "value": "Remo Coated Ambassador"}, {"label": "Afinadores", "value": "10, Imperial lugs"}]'::jsonb),
  ('kali-audio-lp-6-v2', 'LP-6 V2', 'Kali Audio', 'audio', 'monitores', 169, 'El monitor que cambió lo que se espera por su precio: respuesta plana, imagen estéreo amplia y controles de compensación para colocarlo contra una pared o sobre el escritorio. Precio por unidad.', 12, false, ARRAY['https://images.unsplash.com/photo-1563330232-57114bb0823c?auto=format&fit=crop&w=1100&h=1375&q=70','https://images.unsplash.com/photo-1487215078519-e21cc028cb29?auto=format&fit=crop&w=1100&h=1375&q=70']::text[], '[{"label": "Woofer", "value": "6.5\" de papel revestido"}, {"label": "Tweeter", "value": "1\" de tela con guía de onda 3D"}, {"label": "Potencia", "value": "Clase D biamplificada, 80 W total"}, {"label": "Respuesta", "value": "39 Hz - 25 kHz (-10 dB)"}, {"label": "Entradas", "value": "XLR y TRS balanceadas, RCA"}, {"label": "Ajustes", "value": "Boundary EQ de 8 posiciones"}]'::jsonb),
  ('focusrite-scarlett-2i2-4g', 'Scarlett 2i2 4ª gen', 'Focusrite', 'audio', 'interfaces', 199, 'La interfaz de escritorio de referencia para empezar a grabar: dos previos con modo Air, botón Auto Gain que ajusta niveles solo y conversión de 24 bit / 192 kHz. Conexión USB-C con muy baja latencia.', 12, true, ARRAY['https://images.unsplash.com/photo-1535406208535-1429839cfd13?auto=format&fit=crop&w=1100&h=1375&q=70','https://images.unsplash.com/photo-1590602847861-f357a9332bbc?auto=format&fit=crop&w=1100&h=1375&q=70']::text[], '[{"label": "Entradas", "value": "2 combo XLR/TRS con previos Scarlett"}, {"label": "Salidas", "value": "2 monitor TRS + audífonos independiente"}, {"label": "Conversión", "value": "24 bit / 192 kHz"}, {"label": "Ganancia", "value": "69 dB, con Auto Gain y Clip Safe"}, {"label": "Conexión", "value": "USB-C, alimentada por bus"}, {"label": "Incluye", "value": "Ableton Live Lite y Hitmaker Expansion"}]'::jsonb),
  ('shure-sm7db', 'SM7dB', 'Shure', 'audio', 'microfonos', 499, 'El SM7B de siempre para voz y locución, ahora con un previo activo conmutable de hasta +28 dB para que funcione con cualquier interfaz sin un elevador externo. Rechazo de ruido y blindaje electromagnético intactos.', 0, true, ARRAY['https://images.unsplash.com/photo-1590602847861-f357a9332bbc?auto=format&fit=crop&w=1100&h=1375&q=70','https://images.unsplash.com/photo-1478737270239-2f02b77fc618?auto=format&fit=crop&w=1100&h=1375&q=70']::text[], '[{"label": "Tipo", "value": "Dinámico de bobina móvil"}, {"label": "Patrón", "value": "Cardioide"}, {"label": "Respuesta", "value": "50 Hz - 20 kHz con filtros de presencia"}, {"label": "Previo integrado", "value": "0 / +18 / +28 dB, requiere phantom"}, {"label": "Salida", "value": "XLR balanceada"}, {"label": "Incluye", "value": "Filtro antipop A7WS y brazo interno"}]'::jsonb),
  ('beyerdynamic-dt-770-pro', 'DT 770 PRO 80 Ω', 'beyerdynamic', 'audio', 'audifonos', 159, 'Audífono cerrado de estudio con un grave firme y un agudo detallado que perdona horas largas de sesión. Fabricado en Alemania y pensado para repararse: casi todas sus piezas son reemplazables.', 12, false, ARRAY['https://images.unsplash.com/photo-1487215078519-e21cc028cb29?auto=format&fit=crop&w=1100&h=1375&q=70','https://images.unsplash.com/photo-1618366712010-f4ae9c647dcb?auto=format&fit=crop&w=1100&h=1375&q=70']::text[], '[{"label": "Tipo", "value": "Cerrado, circumaural"}, {"label": "Impedancia", "value": "80 ohmios"}, {"label": "Respuesta", "value": "5 Hz - 35 kHz"}, {"label": "Cable", "value": "3 m fijo, en espiral"}, {"label": "Almohadillas", "value": "Terciopelo, reemplazables"}, {"label": "Peso", "value": "270 g sin cable"}]'::jsonb)
